package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Board 05: a cancellable local app-selection draft. Never starts an alarm. */
public final class GuardActivity extends Activity {
    interface Preferences {SharedPreferences open(Context c);}
    static Preferences preferences=Prefs::of;
    private final Set<String> selected=new HashSet<>();
    private List<App> apps=List.of();private boolean enabled,loaded,resumed;private String token,error="";
    private TextView appCount;private Dialog appPicker;private Set<String> pickerSelection;private Bundle restoreAppPicker;
    private SharedPreferences saved;private final Handler handler=new Handler(Looper.getMainLooper());
    private final ExecutorService reader=Executors.newSingleThreadExecutor();
    private static final int PANEL=0xff342b40,INK=0xfff5eafa,MUTED=0xffd0bce9;
    private static final class App {final String pkg,name;App(String p,String n){pkg=p;name=n;}}
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);saved=preferences.open(this);enabled=saved.getBoolean("bedGuard",false);selected.addAll(saved.getStringSet("blocked",Set.of()));if(state!=null){enabled=state.getBoolean("enabled");selected.clear();selected.addAll(state.getStringArrayList("selected"));token=state.getString("token");restoreAppPicker=state.getBundle("appPicker");ArrayList<String> choices=state.getStringArrayList("pickerSelection");if(choices!=null)pickerSelection=new HashSet<>(choices);}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();reader.execute(()->{try{List<ResolveInfo> found=getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),PackageManager.MATCH_ALL);Map<String,App> unique=new HashMap<>();for(ResolveInfo app:found){String pkg=app.activityInfo.packageName;if(safe(pkg))unique.put(pkg,new App(pkg,app.loadLabel(getPackageManager()).toString()));}List<App> result=new ArrayList<>(unique.values());result.sort(Comparator.comparing(a->a.name.toLowerCase(Locale.ROOT)));runOnUiThread(()->{if(!isDestroyed()){apps=result;loaded=true;render();}});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()){loaded=true;error="Apps could not be read. Reopen this screen to try again.";render();}});}});}
    private boolean safe(String pkg){return !pkg.equals(getPackageName())&&!pkg.equals("com.android.settings")&&!pkg.contains("dialer")&&!pkg.contains("incallui")&&!pkg.contains("emergency")&&!pkg.contains("permissioncontroller")&&!pkg.startsWith("com.android.systemui");}
    private boolean access(){String value=Settings.Secure.getString(getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);return value!=null&&value.contains(getPackageName()+"/");}
    private void render(){appCount=null;LinearLayout body=Design.darkPage(this);Design.pad(body,24,8);RecordUi.label(this,body);LinearLayout header=Design.row(this);View back=Design.iconButton(this,"back","Back",this::finish);((Design.Icon)back).tint(INK);header.addView(back,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));header.addView(Design.text(this,"Bedtime guard",25,600,INK),new LinearLayout.LayoutParams(0,-2,1));body.addView(header,new LinearLayout.LayoutParams(-1,-2));Design.space(body,14);Design.text(body,"Block distracting apps during your sleep time.",15,400,MUTED);Design.space(body,14);
        long pauseUntil=saved.getLong("focusPauseUntil",0);boolean paused=pauseUntil>System.currentTimeMillis();handler.removeCallbacks(refreshPause);if(paused&&resumed)handler.postDelayed(refreshPause,pauseUntil-System.currentTimeMillis()+50);SleepPlan plan=SleepPlans.load(this);LinearLayout schedule=Design.row(this);Design.pad(schedule,16,14);schedule.setBackground(Design.shape(this,PANEL,18));glyph(schedule,"clock");LinearLayout text=Design.col(this);Design.text(text,paused?"Paused until "+Design.clock(this,java.time.Instant.ofEpochMilli(pauseUntil).atZone(java.time.ZoneId.systemDefault()).toLocalTime().toSecondOfDay()/60):"Schedule",16,500,INK);Design.space(text,7);Design.text(text,Design.clock(this,Math.floorMod(plan.bedtime-plan.windDown,1440))+" – "+Design.clock(this,plan.wake),16,600,MUTED);schedule.addView(text,new LinearLayout.LayoutParams(0,-2,1));Switch toggle=new Switch(this);toggle.setContentDescription("Bedtime schedule");Design.styleSwitch(this,toggle,Design.VIOLET,0xff51485e);toggle.setChecked(enabled);toggle.setOnCheckedChangeListener((v,on)->enabled=on);schedule.addView(toggle);body.addView(schedule);if(!access()){Design.space(body,10);TextView required=Design.text(body,"Enable accessibility to block apps  →",12,500,MUTED);required.setMinimumHeight(Design.dp(this,48));required.setGravity(Gravity.CENTER_VERTICAL);required.setOnClickListener(v->disclosure());}Design.space(body,12);
        LinearLayout appHeading=Design.row(this);appHeading.addView(Design.text(this,"Select apps to block",19,600,INK),new LinearLayout.LayoutParams(0,-2,1));View choose=Design.iconButton(this,"plus","Choose other apps",this::choose);((Design.Icon)choose).tint(Design.LILAC);choose.setEnabled(token==null&&loaded&&!apps.isEmpty());appHeading.addView(choose,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));body.addView(appHeading);Design.space(body,4);Design.text(body,"These apps will be unavailable during bedtime.",13,400,MUTED);Design.space(body,12);
        if(!loaded)Design.text(body,"Loading your apps…",14,400,MUTED);
        else {List<App> shown=new ArrayList<>();for(App app:apps)if(shown.size()<4&&selected.contains(app.pkg))shown.add(app);for(App app:apps)if(shown.size()<4&&!selected.contains(app.pkg))shown.add(app);if(shown.isEmpty())Design.text(body,"No launchable apps are available.",14,400,MUTED);for(App app:shown){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,52));appIcon(row,app);TextView label=Design.text(this,app.name,16,500,INK);label.setMaxLines(2);label.setEllipsize(android.text.TextUtils.TruncateAt.END);label.setTooltipText(app.name);LinearLayout.LayoutParams textLayout=new LinearLayout.LayoutParams(0,-2,1);textLayout.rightMargin=Design.dp(this,12);row.addView(label,textLayout);Switch block=new Switch(this);block.setContentDescription("Block "+app.name);Design.styleSwitch(this,block,Design.VIOLET,0xff51485e);block.setChecked(selected.contains(app.pkg));block.setOnCheckedChangeListener((v,on)->{if(on)selected.add(app.pkg);else selected.remove(app.pkg);updateAppCount();});row.addView(block);body.addView(row);line(body);}if(selected.size()>4){Design.space(body,8);appCount=Design.text(body,"",12,400,MUTED);updateAppCount();}}
        if(!error.isEmpty()){Design.space(body,12);Design.text(body,error,13,500,MUTED);}Design.space(body,16);
        LinearLayout calls=Design.row(this);Design.pad(calls,14,12);calls.setBackground(Design.shape(this,PANEL,18));ImageView handset=new ImageView(this);handset.setImageResource(android.R.drawable.sym_action_call);handset.setImageTintList(android.content.res.ColorStateList.valueOf(MUTED));handset.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);LinearLayout.LayoutParams handsetLayout=new LinearLayout.LayoutParams(Design.dp(this,28),Design.dp(this,28));handsetLayout.rightMargin=Design.dp(this,18);calls.addView(handset,handsetLayout);LinearLayout copy=Design.col(this);Design.text(copy,"Calls remain available",14,500,INK);Design.space(copy,5);Design.text(copy,"Phone calls, Settings and emergency access stay available.",12,400,MUTED);calls.addView(copy,new LinearLayout.LayoutParams(0,-2,1));body.addView(calls);Design.space(body,10);
        LinearLayout footer=RecordUi.footer(body);nightButton(footer,token==null?"Save blocked apps":"Saving…",true,this::save).setEnabled(token==null&&loaded);Button pause=nightButton(footer,paused?"Resume now":"Pause for 5 min",false,()->{if(paused)saved.edit().remove("focusPauseUntil").apply();else saved.edit().putLong("focusPauseUntil",System.currentTimeMillis()+5*60000L).apply();render();});pause.setEnabled(token==null&&saved.getBoolean("bedGuard",false));pause.setAlpha(pause.isEnabled()?1:.45f);pauseIcon(pause);if(token!=null)RecordUi.enabled(body,false);restorePicker();
    }
    private void updateAppCount(){if(appCount!=null){appCount.setText(selected.size()+" apps selected. Choose other apps to review all.");appCount.setVisibility(selected.size()>4?View.VISIBLE:View.GONE);}}
    private void appIcon(LinearLayout row,App app){ImageView icon=new ImageView(this);try{icon.setImageDrawable(getPackageManager().getApplicationIcon(app.pkg));}catch(PackageManager.NameNotFoundException ignored){icon.setImageDrawable(RecordUi.glyph(this,"phone",MUTED,28));}icon.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(Design.dp(this,30),Design.dp(this,30));p.rightMargin=Design.dp(this,16);row.addView(icon,p);}
    private void glyph(LinearLayout row,String icon){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(Design.dp(this,28),Design.dp(this,28));p.rightMargin=Design.dp(this,18);row.addView(new Design.Icon(this,icon,MUTED),p);}
    private void line(LinearLayout body){View v=new View(this);v.setBackgroundColor(0xff51465e);body.addView(v,new LinearLayout.LayoutParams(-1,Design.dp(this,1)));}
    private Button nightButton(LinearLayout body,String title,boolean primary,Runnable action){Button b=Design.button(body,title,primary,action);b.setTextColor(primary?Design.PLUM:Design.LILAC);b.setBackground(primary?Design.touch(this,Design.LILAC,18):Design.outline(this,PANEL,0xff62566d,18));return b;}
    private void pauseIcon(Button button){String title=button.getText().toString();android.text.SpannableString label=new android.text.SpannableString("\ufffc   "+title);label.setSpan(new android.text.style.ImageSpan(RecordUi.glyph(this,title.equals("Resume now")?"play":"pause",Design.LILAC,20),android.text.style.ImageSpan.ALIGN_CENTER),0,1,0);button.setText(label);button.setContentDescription(title);}
    private void choose(){if(token!=null||!loaded||apps.isEmpty())return;showPicker(new HashSet<>(selected),null);}
    private void restorePicker(){if(restoreAppPicker==null||!loaded||apps.isEmpty()||!resumed||!hasWindowFocus()||appPicker!=null)return;Bundle state=restoreAppPicker;restoreAppPicker=null;showPicker(pickerSelection==null?new HashSet<>(selected):new HashSet<>(pickerSelection),state);}
    private void showPicker(Set<String> choice,Bundle state){
        if(appPicker!=null&&appPicker.isShowing())return;SleepPicker.StateDialog dialog=new SleepPicker.StateDialog(this,"guard-apps","Choose apps to block");dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout content=Design.col(this);Design.pad(content,20,20);content.setBackground(Design.outline(this,PANEL,0xff62566d,20));Design.text(content,"Choose apps to block",22,600,INK);Design.space(content,8);Design.text(content,"Use selection updates this draft. Save blocked apps applies it.",12,400,MUTED);Design.space(content,12);
        for(App app:apps){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,52));appIcon(row,app);TextView label=Design.text(this,app.name,15,500,INK);label.setMaxLines(2);label.setEllipsize(android.text.TextUtils.TruncateAt.END);label.setTooltipText(app.name);LinearLayout.LayoutParams textLayout=new LinearLayout.LayoutParams(0,-2,1);textLayout.rightMargin=Design.dp(this,12);row.addView(label,textLayout);Switch block=new Switch(this);block.setContentDescription("Block "+app.name);Design.styleSwitch(this,block,Design.VIOLET,0xff51485e);block.setChecked(choice.contains(app.pkg));block.setOnCheckedChangeListener((v,on)->{if(on)choice.add(app.pkg);else choice.remove(app.pkg);});row.addView(block);row.setOnClickListener(v->block.performClick());content.addView(row);line(content);}
        ScrollView scroll=new ScrollView(this);scroll.addView(content);LinearLayout root=Design.col(this);root.setBackground(Design.shape(this,PANEL,20));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout actions=Design.col(this);Design.pad(actions,20,8);nightButton(actions,"Use selection",true,()->{selected.clear();selected.addAll(choice);dialog.dismiss();render();});nightButton(actions,"Cancel",false,dialog::dismiss);root.addView(actions,new LinearLayout.LayoutParams(-1,-2));dialog.scroll=scroll;dialog.setContentView(root);dialog.setOnDismissListener(ignored->{if(appPicker==dialog){appPicker=null;pickerSelection=null;}});appPicker=dialog;pickerSelection=choice;SleepPicker.show(this,dialog,620);if(state!=null)dialog.onRestoreInstanceState(state);
    }
    private void disclosure(){new AlertDialog.Builder(this).setTitle("Optional app guard").setMessage(getString(R.string.guard_description)).setPositiveButton("Open settings",(d,w)->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))).setNegativeButton("Later",null).show();}
    private void save(){if(token!=null)return;token=UUID.randomUUID().toString();render();observe();}
    private void observe(){if(!resumed||token==null)return;Set<String> packages=new HashSet<>(selected);boolean schedule=enabled;SharedPreferences bound=saved;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{if(!bound.edit().putStringSet("blocked",packages).putBoolean("bedGuard",schedule).commit())throw new IllegalStateException("Your app choices could not be saved.");return null;});if(!operation.done){handler.removeCallbacks(poll);handler.postDelayed(poll,100);return;}PlanOperations.forget(token);token=null;if(operation.error!=null){error=operation.error;render();return;}finish();}
    private final Runnable poll=this::observe,refreshPause=this::render;
    @Override protected void onResume(){super.onResume();resumed=true;render();observe();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(poll);handler.removeCallbacks(refreshPause);super.onPause();}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("enabled",enabled);state.putStringArrayList("selected",new ArrayList<>(selected));state.putString("token",token);if(appPicker!=null&&appPicker.isShowing()){state.putBundle("appPicker",appPicker.onSaveInstanceState());state.putStringArrayList("pickerSelection",new ArrayList<>(pickerSelection));}else if(restoreAppPicker!=null){state.putBundle("appPicker",restoreAppPicker);if(pickerSelection!=null)state.putStringArrayList("pickerSelection",new ArrayList<>(pickerSelection));}}
    @Override public void finish(){if(token!=null){Ui.toast(this,"Please wait for this save to finish.");return;}super.finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){finish();}
    void awaitReaders(long timeoutMs)throws Exception{if(reader.isShutdown()){if(!reader.awaitTermination(timeoutMs,TimeUnit.MILLISECONDS))throw new TimeoutException("App list still loading");}else reader.submit(()->{}).get(timeoutMs,TimeUnit.MILLISECONDS);}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus){Design.focusedSystemBars(this,true);restorePicker();}}
    @Override protected void onDestroy(){if(appPicker!=null)appPicker.dismiss();handler.removeCallbacks(poll);handler.removeCallbacks(refreshPause);reader.shutdown();super.onDestroy();}
}
